create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text default 'User',age int,height_cm numeric,current_weight_kg numeric,goal_weight_kg numeric,protein_min_g numeric default 90,protein_max_g numeric default 100,calorie_target_kcal numeric default 2200,fibre_target_g numeric default 25,pure_veg_days text[] default array['Tuesday'],no_dal_meals text[] default array['lunch','dinner'],gut_friendly_mode boolean default true,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists meal_logs(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,log_date date not null,slot text not null,meal_id text,status text,calories numeric default 0,protein_g numeric default 0,actual_meal_name text,note text,created_at timestamptz default now());
create table if not exists daily_journals(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,journal_date date not null,gas_score int,pain_score int,energy_score int,stress_score int,bowel_status text,weight_kg numeric,note text,created_at timestamptz default now(),unique(user_id,journal_date));
create table if not exists weight_logs(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,log_date date not null,weight_kg numeric not null,source text default 'manual',unique(user_id,log_date));
create table if not exists whoop_daily_metrics(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,metric_date date not null,recovery_score numeric,hrv_ms numeric,resting_hr_bpm numeric,sleep_minutes int,sleep_performance numeric,strain numeric,calories_burned numeric,raw jsonb default '{}',unique(user_id,metric_date));
create table if not exists health_insights(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,category text,title text,body text,evidence jsonb default '{}',severity text default 'info',created_at timestamptz default now());
